// ==== GERADO por scripts/build-workflows.mjs a partir de src/ (sql). Edite em src/ e rode make build. ====
// ── src/cpf.js ──
// Validação de CPF e e-mail, máscara para logs (LGPD).

function soDigitos(s) {
  return String(s ?? '').replace(/\D/g, '');
}

function validarCpf(entrada) {
  const c = soDigitos(entrada);
  if (c.length !== 11 || /^(\d)\1{10}$/.test(c)) return false;
  const dv = (n) => {
    let soma = 0;
    for (let i = 0; i < n; i++) soma += Number(c[i]) * (n + 1 - i);
    const r = (soma * 10) % 11;
    return r === 10 ? 0 : r;
  };
  return dv(9) === Number(c[9]) && dv(10) === Number(c[10]);
}

function formatarCpf(entrada) {
  const c = soDigitos(entrada);
  return `${c.slice(0, 3)}.${c.slice(3, 6)}.${c.slice(6, 9)}-${c.slice(9)}`;
}

// 123.456.789-09 -> ***.456.789-**
function mascararCpf(entrada) {
  const c = soDigitos(entrada);
  return `***.${c.slice(3, 6)}.${c.slice(6, 9)}-**`;
}

// Mascara qualquer CPF (com ou sem pontuação) dentro de um texto livre.
function mascararCpfsNoTexto(texto) {
  return String(texto ?? '').replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, (m) => mascararCpf(m));
}

function validarEmail(s) {
  return /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(String(s ?? '').trim());
}

// Palavras que não são nome (evita "já paguei" virar o nome do cliente).
const NAO_NOME = new Set(['ja', 'já', 'paguei', 'pago', 'ok', 'oi', 'ola', 'olá', 'segue', 'seguem', 'aqui', 'pronto', 'obrigado',
  'obrigada', 'valeu', 'bom', 'boa', 'dia', 'tarde', 'noite', 'meu', 'minha', 'meus', 'dados', 'sim', 'nao', 'não', 'comprovante',
  'pix', 'enviei', 'mandei', 'certo', 'beleza', 'blz', 'tudo', 'bem', 'tá', 'ta', 'esta', 'está']);
const NUM = /[+(]?\d[\d().-]*/g;

// Lê nome, CPF, e-mail e telefone de uma mensagem livre (uma linha por dado, vírgulas ou tudo junto).
// CPF só vale com dígito verificador certo; com telefone=false, 11 dígitos inválidos contam como CPF errado.
// -> { nome?, cpf? (só dígitos), email?, telefone? (DDD+número), cpfInvalido? }
function extrairDados(texto, { telefone: querTelefone = true } = {}) {
  const out = {};
  let t = String(texto ?? '');
  const em = t.match(/[^\s@,;:<>()]+@[^\s@,;:<>()]+\.[a-z]{2,}/i);
  if (em) { out.email = em[0].toLowerCase(); t = t.replace(em[0], ' '); }
  t = t.replace(/\b(meu nome (é|e)|me chamo|nome completo|nome|cpf|e-?mail|telefone|celular|whatsapp|whats|tel|cel|fone)\b\s*[:=-]?/gi, ' ');
  for (const linha of t.split(/[\n,;|]+/)) {
    const nums = linha.match(NUM) ?? [];
    for (let i = 0; i < nums.length; i++) {
      const d = soDigitos(nums[i]);
      if (d.length === 11 && validarCpf(d)) { out.cpf ??= d; continue; }
      if (/^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(nums[i]) || (d.length === 11 && !querTelefone)) { out.cpfInvalido = true; continue; }
      // Telefone pode vir quebrado: "(71) 99999-8888", "+55 71 99999-8888".
      let acc = d;
      let j = i;
      while (acc.length < 10 && j + 1 < nums.length) acc += soDigitos(nums[++j]);
      if (querTelefone && acc.length >= 10 && acc.length <= 13) { out.telefone ??= acc.replace(/^55(?=\d{10,11}$)/, ''); i = j; }
    }
    const palavras = linha.replace(NUM, ' ').replace(/[^\p{L}'’.\s-]/gu, ' ').trim().split(/\s+/).filter((p) => /\p{L}/u.test(p));
    if (!out.nome && palavras.length >= 2 && !palavras.some((p) => NAO_NOME.has(p.toLowerCase()))) {
      const nome = palavras.join(' ');
      if (nome.length <= 100) out.nome = nome;
    }
  }
  return out;
}

// ── src/sql.js ──
// Monta o SQL que grava o resultado do core num único statement (CTEs).
// Literais escapados aqui (standard_conforming_strings=on, padrão do Postgres).



function lit(v) {
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'object') return `${lit(JSON.stringify(v))}::jsonb`;
  const s = String(v).replace(/\0/g, '').replace(/'/g, "''");
  // O node Postgres do n8n formata a query com pg-promise: "$1" num texto de cliente viraria
  // placeholder. Texto com $ vai como U&'' com o $ em \0024.
  if (!s.includes('$')) return `'${s}'`;
  return `U&'${s.replace(/\\/g, '\\\\').replace(/\$/g, '\\0024')}'`;
}

const COLUNAS_PEDIDO = ['comprovante_url', 'nome', 'cpf', 'email', 'telefone', 'status'];

// ctx = entrada do core; r = resultado de processar(). Devolve 1 linha: {pedido_id}.
function sqlGravar(ctx, r) {
  const ctes = [];
  const { novoPedido, atualizarPedido, novaOferta } = r.efeitos ?? {};
  const canal = lit(ctx.canal);
  const contato = lit(ctx.contato_id);

  if (novoPedido) {
    const p = novoPedido;
    ctes.push(`np as (insert into app.pedidos (canal, contato_id, evento_id, quantidade, valor_total, forma, status)
  values (${canal}, ${contato}, ${lit(p.evento_id)}, ${lit(p.quantidade)}, ${lit(p.valor_total)}, ${lit(p.forma)}, ${lit(p.status)}) returning id)`);
  }
  if (atualizarPedido?.id) {
    const sets = COLUNAS_PEDIDO.filter((k) => k in atualizarPedido).map((k) => `${k}=${lit(atualizarPedido[k])}`);
    ctes.push(`up as (update app.pedidos set ${sets.join(', ')}, atualizado_em=now()
  where id=${Number(atualizarPedido.id)} and canal=${canal} and contato_id=${contato} and status not in ('aprovado','recusado','cancelado'))`);
  }
  if (novaOferta) {
    const o = novaOferta;
    ctes.push(`nov as (insert into app.ofertas_venda (canal, contato_id, evento_texto, quantidade, setor, valor_pedido)
  values (${canal}, ${contato}, ${lit(o.evento_texto)}, ${lit(o.quantidade)}, ${lit(o.setor)}, ${lit(o.valor_pedido)}))`);
  }
  const hist = [];
  const entrada = [ctx.midia ? `[${ctx.midia.tipo}]` : '', ctx.texto ?? ''].filter(Boolean).join(' ');
  if (entrada) hist.push(['in', entrada]);
  for (const m of r.mensagens ?? []) hist.push(['out', m.texto ?? m.url ?? '']);
  if (hist.length) {
    ctes.push(`h as (insert into app.historico (canal, contato_id, direcao, texto) values
  ${hist.map(([d, t]) => `(${canal}, ${contato}, ${lit(d)}, ${lit(mascararCpfsNoTexto(t))})`).join(',\n  ')})`);
  }
  const ctxJson = lit(r.contexto ?? {});
  const ctxFinal = novoPedido ? `${ctxJson} || jsonb_build_object('pedido_id', (select id from np))` : ctxJson;
  ctes.push(`cv as (insert into app.conversas (canal, contato_id, nome, estado, contexto, pausado_ate, atualizado_em)
  values (${canal}, ${contato}, ${lit(ctx.nome || null)}, ${lit(r.estado)}, ${ctxFinal}, ${lit(r.pausado_ate)}, now())
  on conflict (canal, contato_id) do update set nome=coalesce(excluded.nome, app.conversas.nome), estado=excluded.estado,
  contexto=excluded.contexto, pausado_ate=excluded.pausado_ate, atualizado_em=now())`);
  return `with ${ctes.join(',\n')}\nselect ${novoPedido ? '(select id from np)' : 'null::int'} as pedido_id`;
}

// Tudo que o core precisa numa ida ao banco: conversa, eventos ativos, textos e config.
function sqlCarregar(canal, contatoId) {
  return `select
  (select to_jsonb(c) from app.conversas c where c.canal=${lit(canal)} and c.contato_id=${lit(contatoId)}) as conversa,
  (select coalesce(jsonb_agg(to_jsonb(e) order by e.data_evento), '[]') from app.eventos e where e.ativo) as eventos,
  (select coalesce(jsonb_object_agg(chave, texto), '{}') from app.mensagens) as textos,
  (select coalesce(jsonb_object_agg(chave, valor), '{}') from app.config) as config,
  now() as agora`;
}
// ==== fim do código gerado ====

const e = $input.first().json;
return [{ json: { sql: sqlCarregar(e.canal, e.contato_id) } }];

// ==== GERADO por scripts/build-workflows.mjs a partir de src/ (estados). Edite em src/ e rode make build. ====
// ── src/templates.js ──
// Textos padrão do bot e renderização de templates.
// Fonte única: db/mensagens.sql é gerado daqui (scripts/build-workflows.mjs) e o
// dono edita no NocoDB. Se uma linha sumir do banco, vale o padrão abaixo.

const TEXTOS_PADRAO = {
  boas_vindas: 'Oi{nome_cliente}! Aqui é da BF Tickets 🎟\nComo posso ajudar?\n\n1 - Comprar ingresso\n2 - Vender meu ingresso\n3 - Ver eventos\n4 - Falar com atendente',
  escolher_evento: 'Pra qual evento?\n\n{lista_eventos}\n\nResponde com o número.',
  sem_eventos: 'No momento não temos eventos à venda. Vou chamar alguém da equipe pra te ajudar.',
  pedir_qtd: '{evento} — {preco} cada.\nQuantos ingressos você quer?',
  qtd_invalida: 'Me manda só o número de ingressos (de 1 a {max}).',
  escolher_pagamento: 'Fechado: {quantidade}x {evento} = {total}.\nComo prefere pagar?\n\n1 - Link de compra (cartão)\n2 - Pix',
  enviar_link: 'Aqui o link oficial pra garantir o seu:',
  link_fim: 'Qualquer dúvida é só chamar 😉',
  resumo_pix: 'Resumo do pedido:\n🎟 {evento}\n🔢 {quantidade} ingresso(s)\n💰 Total: {total}\n\nA chave Pix vem na próxima mensagem 👇',
  pix_instrucao: 'Titular: {pix_titular} ({pix_banco}).\nDepois de pagar, manda aqui o comprovante (foto ou print).',
  // Instagram: o pedido do comprovante é a pergunta da coleta de imagem do ManyChat (manychat/SETUP.md).
  pix_titular: 'Titular: {pix_titular} ({pix_banco}).',
  lembrar_comprovante: 'Tô aguardando o comprovante do Pix (foto ou print) pra seguir com o pedido.',
  // {item_telefone} só aparece no Instagram (no WhatsApp o número já é o do cliente).
  comprovante_recebido: 'Comprovante recebido ✅\nPra emitir o ingresso, me manda numa mensagem só:\n\n• Nome completo\n• CPF\n• E-mail da sua conta na {ticketeira}{item_telefone}\n\n⚠️ O ingresso é enviado pela {ticketeira}, então use o mesmo e-mail da sua conta lá.',
  dados_faltando: 'Quase lá! Ainda falta: {faltando}.',
  cpf_invalido: 'Esse CPF não parece válido. Confere e manda de novo?',
  // Textos do cliente não mostram o número do pedido (só o admin vê, para aprovar).
  aguardando_validacao: 'Pronto! Seu pedido está em validação. Assim que conferirmos o pagamento eu te aviso por aqui.',
  ainda_validando: 'Seu pedido ainda está em validação. Já já te aviso!',
  pedido_aprovado: 'Pagamento confirmado ✅ Seu pedido pra {evento} foi aprovado! O ingresso vai ser enviado pela {ticketeira} pro e-mail que você informou.\n\nObrigado pela preferência de escolher a BF Tickets! 🎟',
  pedido_recusado: 'Não conseguimos validar o seu pedido pra {evento}.{motivo}\nSe precisar, é só chamar.',
  venda_evento: 'Massa! De qual evento é o ingresso que você quer vender?',
  venda_qtd: 'Quantos ingressos?',
  venda_setor: 'Qual o setor/tipo (pista, camarote, meia...)?',
  venda_valor: 'Quanto você quer por cada um?',
  venda_registrada: 'Anotado! Alguém da equipe vai te responder por aqui em breve.',
  info_evento: '{nome}\n📅 {data}\n📍 {local}\n💰 {preco}\n🔗 {link}',
  lista_eventos: 'Eventos com ingresso à venda:\n\n{lista_eventos}',
  nao_entendi: 'Não entendi muito bem 😅',
  chamando_humano: 'Vou chamar alguém da equipe pra continuar com você. Só um instante!',
  cancelado: 'Beleza, cancelei. Se quiser recomeçar é só mandar um oi.',
  midia_nao_suportada: 'Por aqui só consigo ler texto, foto ou PDF. Pode escrever?',
  // avisos ao admin
  admin_comprovante: '🧾 Comprovante recebido — pedido #{pedido_id}\n{canal} · {contato}\n{quantidade}x {evento} = {total}\n\nAinda faltam os dados do cliente. O aviso pra aprovar chega em seguida.',
  admin_validar: '✅ Pedido #{pedido_id} pronto pra validar\n{quantidade}x {evento} = {total}\nTicketeira: {ticketeira_admin}\n{nome_cliente_completo} · CPF {cpf_mascarado}\n{email} · {telefone}\n\n/aprovar {pedido_id}\n/recusar {pedido_id} motivo',
  admin_humano: '🙋 {canal} · {contato} ({nome}) pediu atendente. Bot pausado nesse chat.',
  admin_venda: '💸 Oferta de venda #{oferta_id}\n{canal} · {contato} ({nome})\nEvento: {evento_texto}\nQtd: {quantidade} · Setor: {setor} · Valor: {valor}',
  admin_story: '📲 Hora do story! Arte acima, legenda e link abaixo:',
};

function textoBot(textos, chave, vars = {}) {
  const t = textos?.[chave] ?? TEXTOS_PADRAO[chave] ?? chave;
  return render(t, vars);
}

// {chave} -> valor; chave sem valor fica vazia.
function render(t, vars = {}) {
  return String(t).replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? '') + '');
}

const TZ = 'America/Bahia';

function formatarData(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  const dia = new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, weekday: 'short', day: '2-digit', month: '2-digit' }).format(d);
  const hora = new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' }).format(d);
  return `${dia.replace('.', '')} às ${hora}`;
}

function formatarPreco(v) {
  if (v === null || v === undefined || v === '') return '';
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(v)).replace(/\s/g, ' ');
}

// Nome da ticketeira de origem do evento (Ticketmaker, Ingresse...) para os textos do cliente.
function ticketeira(e) {
  return String(e?.ticketeira ?? '').trim() || 'ticketeira oficial do evento';
}

function varsEvento(e) {
  if (!e) return {};
  return { nome: e.nome, evento: e.nome, data: formatarData(e.data_evento), local: e.local ?? '', link: e.link_compra ?? '', preco: formatarPreco(e.preco), ticketeira: ticketeira(e) };
}

function listaEventos(eventos) {
  return eventos.map((e, i) => `${i + 1} - ${e.nome} (${formatarData(e.data_evento)})`).join('\n');
}

// ── src/extrator.js ──
// Atalhos sem LLM (regex/keywords) e o contrato do LLM extrator.
// O LLM só classifica/extrai; preço, link e textos vêm sempre do banco.

const INTENCOES = ['comprar', 'vender', 'duvida_evento', 'duvida_outra', 'humano', 'cancelar', 'listar_eventos', 'saudacao', 'outro'];

function normalizar(s) {
  return String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}

const NUMEROS = { um: 1, uma: 1, dois: 2, duas: 2, tres: 3, quatro: 4, cinco: 5, seis: 6, sete: 7, oito: 8, nove: 9, dez: 10 };

// "2", "2 ingressos", "dois", "quero 3 ingressos" -> número
function extrairQuantidade(texto) {
  const t = normalizar(texto);
  let m = t.match(/^(\d{1,3})(\s*(ingressos?|unidades?|x))?[.!]?$/);
  if (m) return Number(m[1]);
  m = t.match(/\b(\d{1,3})\s*(ingressos?|entradas?)\b/);
  if (m) return Number(m[1]);
  m = t.match(/^(?:quero\s+)?(um|uma|dois|duas|tres|quatro|cinco|seis|sete|oito|nove|dez)(\s+ingressos?)?[.!]?$/);
  if (m) return NUMEROS[m[1]];
  m = t.match(/\b(um|uma|dois|duas|tres|quatro|cinco|seis|sete|oito|nove|dez)\s+(ingressos?|entradas?)\b/);
  if (m) return NUMEROS[m[1]];
  return null;
}

// Resposta de menu "1", "2)", "opção 2"
function opcaoMenu(texto) {
  const m = normalizar(texto).match(/^(?:opcao\s*)?(\d{1,2})\s*[).-]?$/);
  return m ? Number(m[1]) : null;
}

const PALAVRAS_VAZIAS = new Set(['show', 'festa', 'evento', 'com', 'para', 'pra', 'dos', 'das', 'the', 'and', 'tour', 'ingresso']);

// Evento citado pelo nome (inteiro ou palavra distintiva de >=4 letras que só um evento tem).
function acharEvento(texto, eventos) {
  const t = normalizar(texto);
  const inteiro = eventos.filter((e) => t.includes(normalizar(e.nome)));
  if (inteiro.length === 1) return inteiro[0];
  const palavras = (e) => normalizar(e.nome).split(/[^a-z0-9]+/).filter((p) => p.length >= 4 && !PALAVRAS_VAZIAS.has(p));
  const achados = eventos.filter((e) => palavras(e).some((p) => new RegExp(`\\b${p}\\b`).test(t)));
  return achados.length === 1 ? achados[0] : null;
}

const KW = {
  cancelar: /^(cancelar|cancela|recomecar|reiniciar|menu|sair|voltar ao inicio|comecar de novo)[.!]?$/,
  humano: /\b(atendente|humano|pessoa real|falar com (alguem|uma pessoa|voce)|suporte)\b/,
  listar_eventos: /^(eventos|ver eventos|quais (sao os )?eventos.*|lista de eventos|agenda)\??$/,
  vender: /\b(vender|revender|vendo (meu|minha|um|uma|\d)|repassar)\b/,
  duvida_evento: /\b(quando|que dia|que horas|horario|data|onde|local|endereco|quanto (custa|e|ta|esta)|preco|valor)\b/,
  comprar: /\b(comprar|compra|quero (ingresso|ir)|tem ingresso|ingressos?|garantir)\b/,
  saudacao: /^(oi+|ola|opa|e ai|eai|bom dia|boa tarde|boa noite|hey|hello|salve)[!.,\s]*$/,
};

// Tenta resolver sem LLM. Retorna {intencao?, evento_id?, quantidade?, confianca} ou null.
function atalhos(texto, eventos = []) {
  const t = normalizar(texto);
  if (!t) return null;
  const evento = acharEvento(t, eventos);
  const quantidade = extrairQuantidade(t);
  const base = { evento_id: evento?.id ?? null, quantidade, confianca: 1 };
  if (KW.cancelar.test(t)) return { ...base, intencao: 'cancelar' };
  if (KW.humano.test(t)) return { ...base, intencao: 'humano' };
  if (KW.listar_eventos.test(t)) return { ...base, intencao: 'listar_eventos' };
  if (KW.saudacao.test(t)) return { ...base, intencao: 'saudacao' };
  if (KW.vender.test(t)) return { ...base, intencao: 'vender' };
  if (KW.duvida_evento.test(t) && !/^\d/.test(t)) return { ...base, intencao: 'duvida_evento' };
  if (KW.comprar.test(t) || evento || quantidade) return { ...base, intencao: 'comprar' };
  return null;
}

// Só intenções globais (estados de coleta: nome/cpf/e-mail/venda não passam pelo LLM).
function intencaoGlobal(texto) {
  const t = normalizar(texto);
  if (KW.cancelar.test(t)) return 'cancelar';
  if (KW.humano.test(t)) return 'humano';
  if (KW.listar_eventos.test(t)) return 'listar_eventos';
  return null;
}

// Corpo da chamada à API Messages da Anthropic (POST /v1/messages). `prompt` vem de prompts/extrator.md.
// Haiku 5.5 rejeita temperature/top_p/top_k (por isso ficam de fora: o determinismo vem do prompt curto
// e do JSON fechado) e pensa por padrão: desligado + effort low, porque só classificamos.
function pedidoLLM({ prompt, modelo, texto, estado, eventos }) {
  const lista = eventos.map((e) => `${e.id}: ${e.nome}`).join('\n') || '(nenhum)';
  return {
    model: modelo,
    max_tokens: 300,
    thinking: { type: 'disabled' },
    output_config: { effort: 'low' },
    system: prompt,
    messages: [{ role: 'user', content: `Estado: ${estado}\nEventos ativos:\n${lista}\n\nMensagem: ${texto}` }],
  };
}

// Lê a resposta do LLM e devolve um objeto seguro (valores fora do contrato viram null).
function lerRespostaLLM(resp, eventos = []) {
  const vazio = { intencao: 'outro', evento_id: null, quantidade: null, nome: null, cpf: null, email: null, confianca: 0 };
  try {
    const conteudo = (resp?.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
    const json = JSON.parse(conteudo.slice(conteudo.indexOf('{'), conteudo.lastIndexOf('}') + 1));
    const ids = new Set(eventos.map((e) => Number(e.id)));
    const q = Number(json.quantidade);
    return {
      intencao: INTENCOES.includes(json.intencao) ? json.intencao : 'outro',
      evento_id: ids.has(Number(json.evento_id)) ? Number(json.evento_id) : null,
      quantidade: Number.isInteger(q) && q > 0 ? q : null,
      nome: typeof json.nome === 'string' && json.nome.trim() ? json.nome.trim() : null,
      cpf: typeof json.cpf === 'string' ? json.cpf : null,
      email: typeof json.email === 'string' ? json.email : null,
      confianca: Math.max(0, Math.min(1, Number(json.confianca) || 0)),
    };
  } catch {
    return vazio;
  }
}

// ── src/cpf.js ──
// Validação de CPF e e-mail, máscara para logs (LGPD).

function soDigitos(s) {
  return String(s ?? '').replace(/\D/g, '');
}

function validarCpf(entrada) {
  const c = soDigitos(entrada);
  if (c.length !== 11 || /^(\d)\1{10}$/.test(c)) return false;
  const dv = (n) => {
    let soma = 0;
    for (let i = 0; i < n; i++) soma += Number(c[i]) * (n + 1 - i);
    const r = (soma * 10) % 11;
    return r === 10 ? 0 : r;
  };
  return dv(9) === Number(c[9]) && dv(10) === Number(c[10]);
}

function formatarCpf(entrada) {
  const c = soDigitos(entrada);
  return `${c.slice(0, 3)}.${c.slice(3, 6)}.${c.slice(6, 9)}-${c.slice(9)}`;
}

// 123.456.789-09 -> ***.456.789-**
function mascararCpf(entrada) {
  const c = soDigitos(entrada);
  return `***.${c.slice(3, 6)}.${c.slice(6, 9)}-**`;
}

// Mascara qualquer CPF (com ou sem pontuação) dentro de um texto livre.
function mascararCpfsNoTexto(texto) {
  return String(texto ?? '').replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, (m) => mascararCpf(m));
}

function validarEmail(s) {
  return /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(String(s ?? '').trim());
}

// Palavras que não são nome (evita "já paguei" virar o nome do cliente).
const NAO_NOME = new Set(['ja', 'já', 'paguei', 'pago', 'ok', 'oi', 'ola', 'olá', 'segue', 'seguem', 'aqui', 'pronto', 'obrigado',
  'obrigada', 'valeu', 'bom', 'boa', 'dia', 'tarde', 'noite', 'meu', 'minha', 'meus', 'dados', 'sim', 'nao', 'não', 'comprovante',
  'pix', 'enviei', 'mandei', 'certo', 'beleza', 'blz', 'tudo', 'bem', 'tá', 'ta', 'esta', 'está']);
const NUM = /[+(]?\d[\d().-]*/g;

// Lê nome, CPF, e-mail e telefone de uma mensagem livre (uma linha por dado, vírgulas ou tudo junto).
// CPF só vale com dígito verificador certo; com telefone=false, 11 dígitos inválidos contam como CPF errado.
// -> { nome?, cpf? (só dígitos), email?, telefone? (DDD+número), cpfInvalido? }
function extrairDados(texto, { telefone: querTelefone = true } = {}) {
  const out = {};
  let t = String(texto ?? '');
  const em = t.match(/[^\s@,;:<>()]+@[^\s@,;:<>()]+\.[a-z]{2,}/i);
  if (em) { out.email = em[0].toLowerCase(); t = t.replace(em[0], ' '); }
  t = t.replace(/\b(meu nome (é|e)|me chamo|nome completo|nome|cpf|e-?mail|telefone|celular|whatsapp|whats|tel|cel|fone)\b\s*[:=-]?/gi, ' ');
  for (const linha of t.split(/[\n,;|]+/)) {
    const nums = linha.match(NUM) ?? [];
    for (let i = 0; i < nums.length; i++) {
      const d = soDigitos(nums[i]);
      if (d.length === 11 && validarCpf(d)) { out.cpf ??= d; continue; }
      if (/^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(nums[i]) || (d.length === 11 && !querTelefone)) { out.cpfInvalido = true; continue; }
      // Telefone pode vir quebrado: "(71) 99999-8888", "+55 71 99999-8888".
      let acc = d;
      let j = i;
      while (acc.length < 10 && j + 1 < nums.length) acc += soDigitos(nums[++j]);
      if (querTelefone && acc.length >= 10 && acc.length <= 13) { out.telefone ??= acc.replace(/^55(?=\d{10,11}$)/, ''); i = j; }
    }
    const palavras = linha.replace(NUM, ' ').replace(/[^\p{L}'’.\s-]/gu, ' ').trim().split(/\s+/).filter((p) => /\p{L}/u.test(p));
    if (!out.nome && palavras.length >= 2 && !palavras.some((p) => NAO_NOME.has(p.toLowerCase()))) {
      const nome = palavras.join(' ');
      if (nome.length <= 100) out.nome = nome;
    }
  }
  return out;
}

// ── src/estados.js ──
// Máquina de estados do atendimento (canal-agnóstica, determinística).
// processar(ctx) -> {precisaLLM, llm} quando o texto livre é ambíguo;
// processar(ctx, respostaLLM) -> {mensagens, acoes, estado, contexto, pausado_ate, efeitos}.
// respostaLLM = objeto cru da API (ou {} se a chamada falhou).





const MAX_QTD = 10;
const CONFIANCA_MIN = 0.6;
const EXPIRA_MS = 24 * 3600 * 1000;
const PRECISA_LLM = Symbol('precisa_llm');
const ESTADOS_COM_PEDIDO = ['aguardando_comprovante', 'coletando_dados'];
const ESTADOS_ANTIGOS = ['coletando_nome', 'coletando_cpf', 'coletando_email']; // viraram coletando_dados

function processar(ctx, respostaLLM) {
  try {
    return executar(ctx, respostaLLM);
  } catch (e) {
    if (e !== PRECISA_LLM) throw e;
    const conv = ctx.conversa ?? {};
    return { precisaLLM: true, llm: pedidoLLM({ prompt: ctx.prompt ?? '', modelo: ctx.modelo, texto: ctx.texto, estado: conv.estado ?? 'inicio', eventos: ctx.eventos ?? [] }) };
  }
}

function executar(ctx, respostaLLM) {
  const agora = new Date(ctx.agora ?? Date.now());
  const cfg = ctx.config ?? {};
  const eventos = ctx.eventos ?? [];
  const textos = ctx.textos ?? {};
  const conv = ctx.conversa ?? {};
  const t = String(ctx.texto ?? '').trim();
  const midia = ctx.midia ?? null;

  let estado = conv.estado || 'inicio';
  if (ESTADOS_ANTIGOS.includes(estado)) estado = 'coletando_dados';
  let c = { ...(conv.contexto ?? {}) };
  let pausado_ate = conv.pausado_ate ?? null;
  const mensagens = [];
  const admin = [];
  const efeitos = {};
  const msg = (chave, vars = {}) => mensagens.push({ tipo: 'texto', texto: textoBot(textos, chave, vars) });
  const fim = () => ({ mensagens, acoes: admin.length ? [{ tipo: 'avisar_admin', mensagens: admin }] : [], estado, contexto: c, pausado_ate, efeitos });

  // Bot desligado ou chat pausado: só registra.
  if (String(cfg.bot_ligado) === 'false') return fim();
  if (pausado_ate && new Date(pausado_ate) > agora) return fim();
  pausado_ate = null;
  if (estado === 'humano' || (conv.atualizado_em && agora - new Date(conv.atualizado_em) > EXPIRA_MS)) {
    estado = 'inicio';
    c = {};
  }

  const evento = (id) => eventos.find((e) => Number(e.id) === Number(id)) ?? null;
  const unico = () => (eventos.length === 1 ? eventos[0] : null);
  const contato = ctx.contato_id;
  const primeiroNome = (ctx.nome ?? '').trim().split(/\s+/)[0];
  const vPedido = () => {
    const e = evento(c.evento_id);
    return { pedido_id: c.pedido_id, evento: e?.nome ?? c.evento_nome ?? '', quantidade: c.quantidade, total: formatarPreco(c.total), ticketeira: ticketeira(e) };
  };
  const querTelefone = ctx.canal === 'instagram'; // no WhatsApp o telefone é o próprio número

  // ── ações reutilizáveis ──
  const humano = () => {
    estado = 'humano';
    const horas = Number(cfg.pausa_humano_horas) || 12;
    pausado_ate = new Date(agora.getTime() + horas * 3600 * 1000).toISOString();
    c.falhas = 0;
    msg('chamando_humano');
    admin.push({ tipo: 'texto', texto: textoBot(textos, 'admin_humano', { canal: ctx.canal, contato, nome: ctx.nome ?? '' }) });
  };
  const boasVindas = () => msg('boas_vindas', { nome_cliente: primeiroNome ? `, ${primeiroNome}` : '' });
  const cancelar = () => {
    if (c.pedido_id && ESTADOS_COM_PEDIDO.includes(estado)) efeitos.atualizarPedido = { id: c.pedido_id, status: 'cancelado' };
    estado = 'inicio';
    c = {};
    msg('cancelado');
  };
  const listar = () => {
    if (!eventos.length) return humanoSemEventos();
    msg('lista_eventos', { lista_eventos: listaEventos(eventos) });
  };
  // Não sabe responder: passa para humano, com o texto de "sem eventos" no lugar de "chamando_humano".
  const humanoSemEventos = () => {
    humano();
    mensagens[mensagens.length - 1] = { tipo: 'texto', texto: textoBot(textos, 'sem_eventos') };
  };
  const duvida = (id) => {
    const e = evento(id) ?? evento(c.evento_id) ?? unico();
    if (e) return msg('info_evento', varsEvento(e));
    if (eventos.length) return listar();
    humanoSemEventos();
  };
  const reperguntar = () => {
    const e = evento(c.evento_id);
    if (estado === 'escolhendo_evento') msg('escolher_evento', { lista_eventos: listaEventos(eventos) });
    else if (estado === 'escolhendo_qtd') msg('pedir_qtd', { evento: e?.nome, preco: formatarPreco(e?.preco) });
    else if (estado === 'escolhendo_pagamento') msg('escolher_pagamento', vPedido());
    else if (estado === 'aguardando_comprovante') msg('lembrar_comprovante');
    else if (estado === 'inicio') boasVindas();
  };
  const falha = () => {
    c.falhas = (c.falhas ?? 0) + 1;
    if (c.falhas >= 2) return humano();
    msg('nao_entendi');
    reperguntar();
  };
  const extrair = () => {
    const a = atalhos(t, eventos);
    if (a) return a;
    if (respostaLLM === undefined) throw PRECISA_LLM;
    return lerRespostaLLM(respostaLLM, eventos);
  };
  // Intenções que valem nos estados de texto livre. true = tratou.
  const tratarIntencao = (e) => {
    switch (e.intencao) {
      case 'cancelar': cancelar(); return true;
      case 'humano': case 'duvida_outra': humano(); return true;
      case 'listar_eventos': listar(); if (estado !== 'inicio') reperguntar(); return true;
      case 'duvida_evento': duvida(e.evento_id); if (estado !== 'inicio') reperguntar(); return true;
      case 'vender': iniciarVenda(e.evento_id); return true;
      default: return false;
    }
  };
  const iniciarCompra = (eventoId, qtd) => {
    if (!eventos.length) return humanoSemEventos();
    const e = evento(eventoId) ?? evento(c.evento_id) ?? unico();
    if (qtd) c.quantidade_pedida = qtd;
    if (!e) {
      estado = 'escolhendo_evento';
      return msg('escolher_evento', { lista_eventos: listaEventos(eventos) });
    }
    c.evento_id = e.id;
    c.evento_nome = e.nome;
    const q = qtd ?? c.quantidade_pedida;
    if (q >= 1 && q <= MAX_QTD) return irParaPagamento(e, q);
    estado = 'escolhendo_qtd';
    msg('pedir_qtd', { evento: e.nome, preco: formatarPreco(e.preco) });
  };
  const irParaPagamento = (e, q) => {
    c.quantidade = q;
    c.total = Math.round(Number(e.preco) * q * 100) / 100;
    delete c.quantidade_pedida;
    estado = 'escolhendo_pagamento';
    msg('escolher_pagamento', vPedido());
  };
  const iniciarVenda = (eventoId) => {
    estado = 'venda_coletando';
    c = { falhas: 0, venda: {} };
    const e = evento(eventoId);
    if (e) {
      c.venda.evento_texto = e.nome;
      c.venda.etapa = 'quantidade';
      return msg('venda_qtd');
    }
    c.venda.etapa = 'evento';
    msg('venda_evento');
  };

  // ── mídia ──
  if (midia) {
    const comprovante = midia.tipo === 'imagem' || (midia.tipo === 'documento' && /pdf/i.test(midia.mimetype ?? 'pdf'));
    if (!comprovante) {
      msg('midia_nao_suportada');
      return fim();
    }
    if (estado === 'aguardando_comprovante') {
      efeitos.atualizarPedido = { id: c.pedido_id, comprovante_url: midia.url ?? midia.ref ?? null, status: 'coletando_dados' };
      admin.push({ ...midia, texto: textoBot(textos, 'admin_comprovante', { ...vPedido(), canal: ctx.canal, contato }) });
      estado = 'coletando_dados';
      msg('comprovante_recebido', { ...vPedido(), item_telefone: querTelefone ? '\n• Telefone com DDD' : '' });
      return fim();
    }
    // Mídia fora de hora (outro comprovante, print...): repassa para um humano.
    admin.push({ ...midia, texto: `📎 Anexo de ${ctx.canal} · ${contato} (${ctx.nome ?? ''}) no estado ${estado}` });
    humano();
    return fim();
  }
  if (!t) return fim();

  // ── intenções globais (keywords, valem em qualquer estado) ──
  const g = intencaoGlobal(t);
  if (g === 'cancelar') { cancelar(); return fim(); }
  if (g === 'humano') { humano(); return fim(); }
  if (g === 'listar_eventos') { listar(); if (estado !== 'inicio') reperguntar(); return fim(); }

  switch (estado) {
    case 'inicio': {
      const op = opcaoMenu(t);
      if (op === 1) iniciarCompra();
      else if (op === 2) iniciarVenda();
      else if (op === 3) listar();
      else if (op === 4) humano();
      else {
        const e = extrair();
        if (e.intencao === 'comprar') { c.falhas = 0; iniciarCompra(e.evento_id, e.quantidade); }
        else if (tratarIntencao(e)) { /* tratado */ }
        else if (e.intencao === 'saudacao' || e.confianca >= CONFIANCA_MIN) boasVindas();
        else falha();
      }
      break;
    }
    case 'escolhendo_evento': {
      const op = opcaoMenu(t);
      let e = op ? eventos[op - 1] : acharEvento(t, eventos);
      if (!e) {
        const x = extrair();
        e = evento(x.evento_id);
        if (!e && tratarIntencao(x)) break;
      }
      if (e) { c.falhas = 0; iniciarCompra(e.id); } else falha();
      break;
    }
    case 'escolhendo_qtd': {
      let q = extrairQuantidade(t);
      if (q === null) {
        const x = extrair();
        if (x.quantidade) q = x.quantidade;
        else if (tratarIntencao(x)) break;
      }
      if (q === null) falha();
      else if (q < 1 || q > MAX_QTD) msg('qtd_invalida', { max: MAX_QTD });
      else { c.falhas = 0; irParaPagamento(evento(c.evento_id), q); }
      break;
    }
    case 'escolhendo_pagamento': {
      const n = normalizar(t);
      const op = opcaoMenu(t);
      const e = evento(c.evento_id);
      if (op === 2 || /\bpix\b/.test(n)) {
        efeitos.novoPedido = { evento_id: e.id, quantidade: c.quantidade, valor_total: c.total, forma: 'pix', status: 'aguardando_comprovante' };
        estado = 'aguardando_comprovante';
        c.falhas = 0;
        msg('resumo_pix', vPedido());
        mensagens.push({ tipo: 'texto', texto: String(cfg.pix_chave ?? '') });
        // No Instagram quem pede o comprovante é a coleta de imagem do ManyChat, aberta logo depois
        // desta resposta: assim a primeira foto do cliente já é capturada (sem mandar duas vezes).
        msg(ctx.canal === 'instagram' ? 'pix_titular' : 'pix_instrucao', { pix_titular: cfg.pix_titular ?? '', pix_banco: cfg.pix_banco ?? '' });
      } else if (op === 1 || /\b(link|cartao|credito|site)\b/.test(n)) {
        msg('enviar_link');
        mensagens.push({ tipo: 'texto', texto: e.link_compra });
        msg('link_fim');
        estado = 'inicio';
        c = {};
      } else {
        const x = extrair();
        if (!tratarIntencao(x)) falha();
      }
      break;
    }
    case 'aguardando_comprovante': {
      const a = atalhos(t, eventos);
      if (!(a && ['duvida_evento', 'vender'].includes(a.intencao) && tratarIntencao(a))) msg('lembrar_comprovante');
      break;
    }
    case 'coletando_dados': {
      // Pede tudo numa mensagem só, mas aceita aos poucos: guarda o que veio e cobra só o que falta.
      const x = extrairDados(t, { telefone: querTelefone });
      const d = (c.dados ??= {});
      const up = {};
      if (x.nome && !d.nome) up.nome = d.nome = x.nome;
      if (x.cpf) { d.cpf_mascarado = mascararCpf(x.cpf); up.cpf = formatarCpf(x.cpf); } // CPF inteiro só em pedidos
      if (x.email && validarEmail(x.email)) up.email = d.email = x.email;
      if (x.telefone) up.telefone = d.telefone = x.telefone;
      if (!querTelefone && !d.telefone) up.telefone = d.telefone = contato;
      const v = vPedido();
      const falta = [!d.nome && 'nome completo', !d.cpf_mascarado && 'CPF', !d.email && `e-mail da sua conta na ${v.ticketeira}`, !d.telefone && 'telefone com DDD'].filter(Boolean);
      if (!falta.length) {
        up.status = 'aguardando_validacao';
        estado = 'aguardando_validacao';
        msg('aguardando_validacao', v);
        const e = evento(c.evento_id);
        admin.push({ tipo: 'texto', texto: textoBot(textos, 'admin_validar', { ...v, ticketeira_admin: e?.ticketeira || 'não cadastrada', nome_cliente_completo: d.nome, cpf_mascarado: d.cpf_mascarado, email: d.email, telefone: d.telefone }) });
      } else {
        if (x.cpfInvalido && !d.cpf_mascarado) msg('cpf_invalido');
        msg('dados_faltando', { faltando: falta.length > 1 ? `${falta.slice(0, -1).join(', ')} e ${falta.at(-1)}` : falta[0] });
      }
      if (Object.keys(up).length) efeitos.atualizarPedido = { id: c.pedido_id, ...up };
      break;
    }
    case 'aguardando_validacao':
      msg('ainda_validando', vPedido());
      break;
    case 'venda_coletando': {
      const v = (c.venda ??= { etapa: 'evento' });
      if (v.etapa === 'evento') {
        v.evento_texto = acharEvento(t, eventos)?.nome ?? t;
        v.etapa = 'quantidade';
        msg('venda_qtd');
      } else if (v.etapa === 'quantidade') {
        const q = extrairQuantidade(t);
        if (q >= 1) { v.quantidade = q; v.etapa = 'setor'; msg('venda_setor'); } else msg('venda_qtd');
      } else if (v.etapa === 'setor') {
        v.setor = t;
        v.etapa = 'valor';
        msg('venda_valor');
      } else {
        const valor = lerValor(t);
        if (valor === null) { msg('venda_valor'); break; }
        efeitos.novaOferta = { evento_texto: v.evento_texto, quantidade: v.quantidade, setor: v.setor, valor_pedido: valor };
        admin.push({ tipo: 'texto', texto: textoBot(textos, 'admin_venda', { canal: ctx.canal, contato, nome: ctx.nome ?? '', evento_texto: v.evento_texto, quantidade: v.quantidade, setor: v.setor, valor: formatarPreco(valor) }) });
        msg('venda_registrada');
        estado = 'inicio';
        c = {};
      }
      break;
    }
    default:
      estado = 'inicio';
      c = {};
      boasVindas();
  }
  return fim();
}

// "R$ 1.250,50", "250", "200 reais" -> número
function lerValor(texto) {
  const m = String(texto).match(/\d[\d.,]*/);
  if (!m) return null;
  let s = m[0];
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/[.,](?=\d{3}\b)/g, '').replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) && n > 0 ? n : null;
}
