const PROMPT = "Você classifica mensagens de clientes de uma revenda de ingressos (BF Tickets) e extrai dados.\nResponda APENAS um objeto JSON, sem texto fora dele:\n{\"intencao\": \"...\", \"evento_id\": null, \"quantidade\": null, \"nome\": null, \"cpf\": null, \"email\": null, \"confianca\": 0.0}\n\nintencao, uma de:\n- comprar: quer ingresso / ir num evento\n- vender: quer vender ou repassar ingresso próprio\n- duvida_evento: pergunta data, horário, local ou preço de um evento\n- duvida_outra: outra pergunta (forma de pagamento, meia-entrada, estacionamento, reembolso...)\n- humano: quer falar com uma pessoa\n- cancelar: quer cancelar ou recomeçar\n- listar_eventos: quer saber quais eventos existem\n- saudacao: só cumprimento\n- outro: nada disso\n\nRegras:\n- evento_id: só um id da lista \"Eventos ativos\" que a mensagem cita com clareza; senão null.\n- quantidade: inteiro de ingressos citado (\"eu e minha namorada\" = 2); senão null.\n- nome, cpf, email: só se aparecerem escritos na mensagem; senão null.\n- confianca: 0 a 1, o quanto tem certeza da intencao.\n- Nunca invente preço, link, data ou evento.";
const e = $('Entrada').first().json;
const d = $input.first().json;
const ctx = { canal: e.canal, contato_id: e.contato_id, nome: e.nome, texto: e.texto, midia: e.midia ?? null,
  conversa: d.conversa, eventos: d.eventos, textos: d.textos, config: d.config, agora: d.agora, prompt: PROMPT, modelo: $env.LLM_MODEL };
const r = processar(ctx);
return [{ json: { ctx, r, precisaLLM: !!r.precisaLLM, llm: r.llm ?? null } }];

// ==== GERADO por scripts/build-workflows.mjs a partir de src/ (estados, sql). Edite em src/ e rode make build. ====
// ── src/templates.js ──
// Textos padrão do bot e renderização de templates.
// Fonte única: db/mensagens.sql é gerado daqui (scripts/build-workflows.mjs) e o
// dono edita no NocoDB. Se uma linha sumir do banco, vale o padrão abaixo.

const TEXTOS_PADRAO = {
  boas_vindas: 'Oi{nome_cliente}! Aqui é da BF Tickets 🎟\nComo posso ajudar?\n\n1 - Comprar ingresso\n2 - Vender meu ingresso\n3 - Ver eventos\n4 - Falar com atendente',
  escolher_evento: 'Pra qual evento?\n\n{lista_eventos}\n\nResponde com o número.',
  sem_eventos: 'No momento não temos eventos à venda. Vou chamar alguém da equipe pra te ajudar.',
